interactions.query:
query ReleaseTags($owner: String!, $repo: String!, $head: String!, $cursor: String) {
  repository(owner: $owner, name: $repo) {
    head: object(expression: $head) { oid }
    refs(refPrefix: "refs/tags/", first: 100, after: $cursor, orderBy: {field: TAG_COMMIT_DATE, direction: DESC}) {
      totalCount
      pageInfo { hasNextPage endCursor }
      nodes {
        name
        target { __typename oid ... on Tag { target { __typename oid } } }
      }
    }
  }
}

query ReleaseCompare($owner: String!, $repo: String!, $base: String!, $head: String!, $cursor: String) {
  repository(owner: $owner, name: $repo) {
    ref(qualifiedName: $base) {
      compare(headRef: $head) {
        status
        aheadBy
        behindBy
        commits(first: 100, after: $cursor) {
          totalCount
          pageInfo { hasNextPage endCursor }
          nodes { ...releaseCommit }
        }
      }
    }
  }
}



fragment releaseCommit on Commit {
  oid
  message
  associatedPullRequests(first: 5) {
    totalCount
    nodes {
      number
      merged
      repository { nameWithOwner }
      mergeCommit { oid }
      closingIssuesReferences(first: 25) {
        totalCount
        nodes { number repository { nameWithOwner } }
      }
    }
  }
}
